import useAuth from "@/hooks/useAuth"
import usePermissions from "@/hooks/usePermissions"
import { PERMISSIONS, requirePermission } from "@/lib/permissions"

function getUsersQueryOptions() {
  return {
    queryFn: async () =>
      (await UsersService.readUsers({ query: { skip: 0, limit: 100 } })).data,
    queryKey: ["users"],
  }
}

export const Route = createFileRoute("/_layout/admin")({
  component: Admin,
  beforeLoad: async () => {
    // users:read lets both admin and manager view the page; anyone else
    // (e.g. a member navigating directly) is redirected home.
    await requirePermission(PERMISSIONS.usersRead)
  },
  head: () => ({
    meta: [
      {
        title: "Admin - FastAPI Template",
      },
    ],
  }),
})

function UsersTableContent() {
  const { user: currentUser } = useAuth()
  const { data: users } = useSuspenseQuery(getUsersQueryOptions())

  const tableData: UserTableData[] = users.data.map((user: UserPublic) => ({
    ...user,
    isCurrentUser: currentUser?.id === user.id,
  }))

  return <DataTable columns={columns} data={tableData} />
}

function UsersTable() {
  return (
    <Suspense fallback={<PendingUsers />}>
      <UsersTableContent />
    </Suspense>
  )
}

function Admin() {
  const { hasPermission } = usePermissions()
  const canManage = hasPermission(PERMISSIONS.usersManage)

  return (
    <div className="flex flex-col gap-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">Users</h1>
          <p className="text-muted-foreground">
            {canManage
              ? "Manage user accounts and permissions"
              : "View user accounts and permissions"}
          </p>
        </div>
        {canManage && <AddUser />}
      </div>
      <UsersTable />
    </div>
  )
}
''')
